# 36. SAVE KERAS 3 MODEL
###############################################################

model_file <-

    "Deep_Affine_Transformer_Compiled.keras"


cat("\n")
cat(
    "Saving Keras 3 model...\n"
)

save_model(

    model,

    model_file,

    overwrite =
        TRUE
)


###############################################################
# 37. VERIFY KERAS MODEL
###############################################################

if (
    !file.exists(model_file)
) {

    stop(
        "Keras model file was not created."
    )
}


###############################################################
# 38. ARCHITECTURE INFORMATION
###############################################################

architecture_info <-

    data.frame(

        Layer = c(

            "Input",
            "Input Projection",
            "Transformer 1",
            "Transformer 2",
            "CNN 1",
            "CNN 2",
            "BiLSTM",
            "Shared Dense",
            "Affine Factors",
            "Affine Pricing",
            "Volatility"

        ),

        Description = c(

            paste0(
                sequence_length,
                " x ",
                feature_dim
            ),

            paste0(
                feature_dim,
                "-dimensional projection"
            ),

            paste0(
                "Multi-head attention: ",
                num_heads,
                " heads x ",
                head_size
            ),

            paste0(
                "Multi-head attention: ",
                num_heads,
                " heads x ",
                head_size
            ),

            paste0(
                cnn_filters_1,
                " filters, kernel size ",
                cnn_kernel_size
            ),

            paste0(
                cnn_filters_2,
                " filters, kernel size ",
                cnn_kernel_size
            ),

            paste0(
                lstm_units,
                " units per direction"
            ),

            paste0(
                dense_units,
                "-unit representation"
            ),

            paste(
                factor_names,
                collapse = ", "
            ),

            paste(
                yield_names,
                collapse = ", "
            ),

            "Positive volatility output"

        ),

        stringsAsFactors =
            FALSE
    )


###############################################################
# 39. EXPORT ARCHITECTURE
###############################################################

write.csv(

    architecture_info,

    "05_ModelArchitecture.csv",

    row.names =
        FALSE
)


###############################################################
# 40. SAVE OUTPUT NAMES
###############################################################

OutputNames <-

    list(

        factor_names =
            factor_names,

        yield_names =
            yield_names,

        volatility_name =
            "Volatility"
    )


save(

    OutputNames,

    file =
        "05D_OutputNames.RData"
)


###############################################################
# 41. FINAL VALIDATION
###############################################################

if (
    sequence_length != 20L
) {

    warning(
        paste0(
            "Sequence length is ",
            sequence_length,
            ", not 20."
        )
    )
}


if (
    feature_dim != 55L
) {

    warning(
        paste0(
            "Feature dimension is ",
            feature_dim,
            ", not 55."
        )
    )
}


if (
    n_factor_outputs != 2L
) {

    stop(
        "The model requires exactly two affine factors: Level and Slope."
    )
}


if (
    n_yield_outputs != 2L
) {

    stop(
        "The model requires exactly two Treasury yields: DGS10 and DTB3."
    )
}


if (
    !identical(
        factor_names,
        c(
            "Level",
            "Slope"
        )
    )
) {

    stop(
        "Affine factor ordering is incorrect."
    )
}


if (
    !identical(
        yield_names,
        c(
            "DGS10",
            "DTB3"
        )
    )
) {

    stop(
        "Yield ordering is incorrect."
    )
}


